//! Example: Read a wind resource grid (WRG) file
//!
//! This example demonstrates wind resource grid (WRG) data handling: the
//! WRG file generated by the previous example is read with the `WindRoseWRG`
//! object, and wind roses at points on the WRG grid (and interpolated
//! in-between points) are retrieved.
//!
//! Scenario aligned 1:1 with
//! examples_wind_resource_grid/001_wind_rose_wrg.py.

use florus::types::Array1;
use florus::wind_data::WindRoseWRG;

fn main() -> anyhow::Result<()> {
    // Read the WRG file
    let mut wind_rose_wrg = WindRoseWRG::new("examples/inputs/wrg_example.wrg", None, None, None)?;

    // Print some basic information (Python: print(wind_rose_wrg))
    let d = &wind_rose_wrg.wrg_data;
    println!(
        "WindResourceGrid with {} x {} grid points, min x: {}, min y: {}, grid size: {}, \
         {} sectors",
        d.nx, d.ny, d.xmin, d.ymin, d.grid_size, d.n_sectors
    );
    println!(
        "Wind directions in file: {:?}",
        wind_rose_wrg.wind_directions
    );
    println!("Wind directions: {:?}", wind_rose_wrg.wind_directions);
    println!("Wind speeds: {:?}", wind_rose_wrg.wind_speeds);
    println!("ti_table rows: {}", wind_rose_wrg.ti_table.shape()[0]);

    // The wind roses were set to have a higher concentration of faster north
    // winds for increasing y; show that this is contained within the wind
    // roses, even those interpolated between grid points.
    let y_points_to_test = Array1::from_vec(vec![0.0, 500.0, 1000.0, 1500.0, 2000.0]);
    for y in y_points_to_test.iter() {
        let rose = wind_rose_wrg.get_wind_rose_at_point(0.0, *y, None, None, None);
        let sum_freq: f64 = rose.freq_table.sum();
        let peak_ws = rose
            .wind_speeds
            .iter()
            .enumerate()
            .max_by(|a, b| a.1.partial_cmp(b.1).unwrap())
            .map(|(i, _)| i)
            .unwrap_or(0);
        println!(
            "y = {:6.0}: wind speed bins {}, frequency sum {:.6}, peak ws bin {}",
            y,
            rose.wind_speeds.len(),
            sum_freq,
            peak_ws
        );
    }

    // Use 2 m/s steps and a fixed TI of 7% (Python example 002)
    wind_rose_wrg.set_wind_speeds(Array1::from_iter((0..13).map(|i| i as f64 * 2.0)));
    wind_rose_wrg.set_ti_table(0.07);
    Ok(())
}
